#include <math.h>
#include <stdio.h>
#include <string.h>

#include "sr_core.h"
#include "sr_p2_visual_color.h"
#include "sr_p4.h"
#include "sr_p4_hk_misc_color.h"
#include "sr_p4_hk_misc_lime_data.h"

/* LimeSlimeFlavors */
int sr_p4_hack_lime_slime_flavors(struct sr_ctx *c) {
  struct sr_random *random = &c->rc;
  /* index into 10bb24 (16 bit) -> bank 2 */
  static const uint8_t pal_indexes[] = {0x5b, 0x5c, 0x5d, 0x5e};

  int flavor_idx = sr_random_next(random) % SR_P4_HMISC_N_FLAVORS;
  const char *flavor = sr_p4_hmisc_flavors[flavor_idx].name;
  const double *fv = sr_p4_hmisc_flavors[flavor_idx].v;
  char name[64];
  snprintf(name, sizeof name, "%s Slime", flavor);
  sr_names_set(c, NAMES_INDEX_ENEMIES_START + 106, name);

  /* slime part + middle part */
  static const int pal_part_starts[] = {1, 12};
  static const int pal_part_ends[] = {9, 15};
  const double orig_hues[] = {(160 / 256.0) * 360, (70 / 256.0) * 360, (0 / 256.0) * 360, (165 / 256.0) * 360};
  const int rainbow = !strcmp(flavor, "Rainbow");

  for (int pal_part = 0; pal_part < 2; pal_part++) {
    double target_h = fv[0 + pal_part * 4];
    double target_s = fv[1 + pal_part * 4];
    double target_v = fv[2 + pal_part * 4];
    double target_v_add = fv[3 + pal_part * 4];

    for (int pi = 0; pi < 4; pi++) {
      int palette_id = pal_indexes[pi];
      int palette_offset = 0x20000 + sr_ushort_from_bytes(c->out, 0x10bb24 + palette_id * 2);
      int palette_read_offset = palette_offset;
      if (palette_id == 0x5e) palette_read_offset = 0x20000 + sr_ushort_from_bytes(c->out, 0x10bb24 + 0x5b * 2);

      /* leave index 0 and 14 out of it though */
      double avg_hue;
      if (pal_part == 1) avg_hue = 10;   /* middle part thing */
      else avg_hue = orig_hues[palette_id - 0x5b];

      double t_h = target_h < 0 ? -1 : target_h;
      double t_s = target_s;
      double t_v = target_v;
      double t_a = target_v_add;
      double hue_shift = t_h < 0 ? -1 : avg_hue - t_h;   /* subtract this later */

      for (int i = pal_part_starts[pal_part]; i <= pal_part_ends[pal_part]; i++) {
        struct sr_w2_color color = {{sr_peek_orig(c, palette_read_offset + i * 2), sr_peek_orig(c, palette_read_offset + i * 2 + 1)}};
        double h, s, v;
        sr_p4_hmisc_rgb_to_hsv(sr_w2_get_red(&color), sr_w2_get_green(&color), sr_w2_get_blue(&color), &h, &s, &v);

        if (palette_id != 0x5e && pal_part == 0) v += 0.2;
        else if (pal_part == 0) v += 0.1;
        double v_diff = (1 - v) * t_v;
        v -= v_diff;
        v += t_a;
        if (v < 0.1) v = 0.1;
        if (v > 1) v = 1;

        if (hue_shift != -1) h -= hue_shift;
        s *= t_s;

        if (pal_part == 1) {
          /* hue flatten */
          double diff_from_th = h - t_h;
          h -= diff_from_th * 0.7;
        }

        if (rainbow) {
          if (pal_part == 1) {
            double ir = (i - pal_part_starts[pal_part]) / (double)(pal_part_ends[pal_part] - pal_part_starts[pal_part]);
            h = ir * 360.0;
          } else if (i == pal_part_starts[pal_part]) {
            v = 0;
          } else {
            double ir = ((i - 1) - pal_part_starts[pal_part]) / (double)(pal_part_ends[pal_part] - pal_part_starts[pal_part]);
            h = ir * 360.0;
          }
        }
        int r, g, b;
        sr_p4_hmisc_hsv_to_rgb(h, s, v, &r, &g, &b);
        struct sr_w2_color color_new = sr_w2_color_rgb(r, g, b);
        sr_poke(c, palette_offset + i * 2, color_new.b[0]);
        sr_poke(c, palette_offset + i * 2 + 1, color_new.b[1]);
      }
    }
  }
  return 1;
}

/* MapPaletteRandomizations */
static void hmisc_shift_color(struct sr_ctx *c, int off, double h_change, double s_change, double v_change) {
  struct sr_w2_color col = {{sr_peek(c, off), sr_peek(c, off + 1)}};
  double h, s, v;
  sr_p4_hmisc_rgb_to_hsv(sr_w2_get_red(&col), sr_w2_get_green(&col), sr_w2_get_blue(&col), &h, &s, &v);
  h += h_change;
  s += s_change;
  if (s < 0.2) s = 0.2;
  v += v_change;
  int r, g, b;
  sr_p4_hmisc_hsv_to_rgb(h, s, v, &r, &g, &b);
  sr_w2_set_red(&col, (uint8_t)r);
  sr_w2_set_green(&col, (uint8_t)g);
  sr_w2_set_blue(&col, (uint8_t)b);
  sr_poke(c, off, col.b[0]);
  sr_poke(c, off + 1, col.b[1]);
}

int sr_p4_hack_map_palette_randomizations(struct sr_ctx *c) {
  struct sr_random *random = &c->rc;
  if (!sr_settings_get_bool(c->settings, "opMapColors")) return 0;

  const char *goal = sr_work_get(c, "openWorldGoalShortName");
  if (!goal) goal = "";
  if (!strcmp(goal, "xmas2020") || !strcmp(goal, "xmas2020b") || sr_settings_get_bool(c->settings, "opXmasMaps")) return 0;

  /* groups of palette sets that share their change: {first, second} */
  static const int groups[2][2] = {{34, 101}, {54, 104}};
  static const int pal_to_disp[][2] = {{25, 4}, {26, 1}, {36, 9}, {103, 18}, {109, 19}, {108, 20}, {118, 23}};
  static const int dont_change[] = {37, 97, 89, 88, 47, 91, 93, 92, 95};
  double prev_h[2] = {0, 0}, prev_s[2] = {0, 0}, prev_v[2] = {0, 0};
  const int pal_start_offset = 0xC7FE0;

  for (int set = 24; set < 120; set++) {
    int skip = 0;
    for (size_t k = 0; k < sizeof dont_change / sizeof *dont_change; k++)
      if (dont_change[k] == set) skip = 1;
    if (skip) continue;

    const double hue_max = 250;
    double h_change = (fmod((double)sr_random_next(random), hue_max * 2) / 1.0) - hue_max;   /* really funky hue */
    double s_change = -fabs(h_change) / 1250.0;   /* hue-dependent; undersaturate if more change */
    double v_change = -fabs(h_change) / 1250.0;   /* hue-dependent; darker if more change */
    for (size_t k = 0; k < sizeof pal_to_disp / sizeof *pal_to_disp; k++)
      if (pal_to_disp[k][0] == set) hmisc_shift_color(c, 0x80100 + pal_to_disp[k][1] * 9 + 7, h_change, s_change, v_change);

    int do_animation = 0;
    for (int g = 0; g < 2; g++) {
      if (groups[g][0] == set) {
        do_animation = 1;
        prev_h[g] = h_change;
        prev_s[g] = s_change;
        prev_v[g] = v_change;
      } else if (groups[g][1] == set) {
        h_change = prev_h[g];
        s_change = prev_s[g];
        v_change = prev_v[g];
      }
    }

    for (int palnum = 1; palnum < 8; palnum++)
      for (int col = 1; col < 16; col++) hmisc_shift_color(c, pal_start_offset + set * 30 * 7 + palnum * 30 + col * 2, h_change, s_change, v_change);

    if (do_animation) {
      int anim_index = sr_peek(c, 0x80802 + set) + 1;
      int anim_pal_index = sr_peek(c, 0x8087B + anim_index);
      if (anim_pal_index >= 0x80) anim_pal_index = sr_peek(c, 0x8087B + anim_index + 1);
      int anim_pal_offset = anim_pal_index * 0x1E + 0x808E4;
      for (int palnum = 0; palnum < 7; palnum++)
        for (int col = 0; col < 15; col++) {
          int off = anim_pal_offset + palnum * 30 + col * 2;
          if (off < 0x80FFE || off > 0x819D6) hmisc_shift_color(c, off, h_change, s_change, v_change);
        }
    }
  }
  return 1;
}
